insert into public.research_method (id, name, description, created_at, updated_at) values
  (1, 'Moderated usability test', 'A facilitator watches a participant attempt set tasks with a prototype or live product.', '2026-05-01T10:00:00+00:00', '2026-05-01T10:00:00+00:00'),
  (2, 'Contextual interview', 'An interview held where the participant normally does the activity.', '2026-05-01T10:00:00+00:00', '2026-05-01T10:00:00+00:00'),
  (3, 'Diary study', 'Participants log their own behaviour over several days or weeks.', '2026-05-01T10:00:00+00:00', '2026-05-01T10:00:00+00:00'),
  (4, 'Unmoderated survey', 'A short questionnaire completed without a facilitator.', '2026-05-01T10:00:00+00:00', '2026-05-01T10:00:00+00:00'),
  (5, 'Card sort', 'Participants group and label content cards to reveal their mental model.', '2026-05-01T10:00:00+00:00', '2026-05-01T10:00:00+00:00');
insert into public.research_project (id, title, description, research_objective, status, start_date, end_date, archived_at, created_at, updated_at) values
