insert into public.observation (id, session_id, title, description, sentiment, created_at, updated_at) values
  (1, 1, 'Stopped at the proof-of-address step', 'P-01 paused for about a minute at ''Upload proof of address'', said they had no utility bill on their phone, and closed the app to look for one.', 'negative', '2026-08-10T15:00:00+00:00', '2026-08-10T15:00:00+00:00'),
  (2, 1, 'Found the step counter reassuring', 'P-01 pointed at the step counter and said it helped to know there were only five steps.', 'positive', '2026-08-10T15:00:00+00:00', '2026-08-10T15:00:00+00:00'),
  (3, 2, 'Unsure which documents count', 'P-02 asked aloud whether a statement from another bank would be accepted. The screen did not say.', 'negative', '2026-08-11T15:00:00+00:00', '2026-08-11T15:00:00+00:00'),
  (4, 2, 'Hesitated at the camera permission', 'P-02 read the camera permission prompt twice and asked why the app needed it before tapping Allow.', 'negative', '2026-08-11T15:00:00+00:00', '2026-08-11T15:00:00+00:00'),
  (5, 3, 'Left the app to find a document', 'P-03 switched to their email to search for an electricity bill, then came back to find the form had reset.', 'negative', '2026-08-12T15:00:00+00:00', '2026-08-12T15:00:00+00:00'),
  (6, 3, 'Identity check was quick once started', 'P-03 finished the selfie check in under a minute and said it was easier than expected.', 'positive', '2026-08-12T15:00:00+00:00', '2026-08-12T15:00:00+00:00'),
  (7, 4, 'Expected a checklist before starting', 'P-04 said their previous bank emailed a list of what to prepare, and they wanted the same here.', 'neutral', '2026-08-14T15:00:00+00:00', '2026-08-14T15:00:00+00:00'),
  (8, 4, 'Enlarged text cut off button labels', 'P-04 uses enlarged system text. The Continue button label was truncated on two screens.', 'negative', '2026-08-14T15:00:00+00:00', '2026-08-14T15:00:00+00:00');
insert into public.finding (id, project_id, title, confidence, created_at, description, updated_at) values
  (1, 1, 'Proof of address is the main drop-off point', 'high', '2026-08-17T10:00:00+00:00', 'Three of four participants stopped at the proof-of-address step because they had no suitable document on their phone.', '2026-08-17T10:00:00+00:00'),
  (2, 1, 'People don''t know what to prepare', 'medium', '2026-08-17T10:00:00+00:00', 'Participants started without knowing which documents would be accepted and expected guidance before step one.', '2026-08-17T10:00:00+00:00'),
  (3, 1, 'The camera request needs a reason', 'medium', '2026-08-17T10:00:00+00:00', 'The system camera prompt appeared without explanation, causing hesitation, although the check itself went smoothly.', '2026-08-17T10:00:00+00:00'),
  (4, 1, 'Progress is lost when people leave the app', 'high', '2026-08-17T10:00:00+00:00', 'Leaving the app to find a document reset the form, forcing participants to start again.', '2026-08-17T10:00:00+00:00'),
  (5, 1, 'Enlarged text breaks key buttons', 'medium', '2026-08-18T10:00:00+00:00', 'With enlarged system text, primary button labels were truncated on two onboarding screens.', '2026-08-18T10:00:00+00:00');
insert into public.insight (id, project_id, title, impact, created_at, description, updated_at) values
  (1, 1, 'New customers start without the documents they need', 'high', '2026-08-20T10:00:00+00:00', 'Account opening assumes people arrive prepared. Most don''t, so the first real task is finding paperwork.', '2026-08-20T10:00:00+00:00'),
  (2, 1, 'Leaving the app is part of the journey', 'high', '2026-08-20T10:00:00+00:00', 'Going to find a document is expected behaviour, so progress has to survive people leaving and returning.', '2026-08-20T10:00:00+00:00'),
  (3, 1, 'Trust comes before the camera', 'medium', '2026-08-20T10:00:00+00:00', 'People accept identity checks once they understand why the camera is needed.', '2026-08-20T10:00:00+00:00');
insert into public.recommendation (id, project_id, title, priority, status, created_at, description, updated_at) values
  (1, 1, 'Show a ''what you''ll need'' checklist before step one', 'high', 'accepted', '2026-08-24T10:00:00+00:00', 'List accepted documents and examples on a preparation screen before the form begins.', '2026-08-24T10:00:00+00:00'),
  (2, 1, 'Save progress automatically and resume where people left off', 'high', 'accepted', '2026-08-24T10:00:00+00:00', 'Store a draft after each step so returning to the app restores the form.', '2026-08-24T10:00:00+00:00'),
  (3, 1, 'Explain the camera before the system prompt', 'medium', 'accepted', '2026-08-24T10:00:00+00:00', 'Show a short explanation of the identity check before triggering the operating system permission.', '2026-08-24T10:00:00+00:00'),
  (4, 1, 'Accept a wider range of address documents', 'medium', 'proposed', '2026-08-25T10:00:00+00:00', 'Allow statements from other banks and digital letters as proof of address.', '2026-08-25T10:00:00+00:00');
insert into public.design_decision (id, project_id, title, status, decided_on, created_at, description, updated_at) values
  (1, 1, 'Add a preparation screen to account opening', 'implemented', '2026-09-02', '2026-09-02T10:00:00+00:00', 'A preparation screen listing accepted documents now opens the flow, so people gather paperwork before starting.', '2026-09-02T10:00:00+00:00'),
  (2, 1, 'Keep onboarding drafts for seven days', 'approved', '2026-09-04', '2026-09-04T10:00:00+00:00', 'Drafts persist for seven days so people can leave to find documents without losing progress.', '2026-09-04T10:00:00+00:00'),
  (3, 1, 'Add a pre-permission screen for camera access', 'implemented', '2026-09-02', '2026-09-02T10:00:00+00:00', 'A screen explaining the identity check appears before the system camera prompt.', '2026-09-02T10:00:00+00:00');
